float form_rep_predict(const float x[31]) {
    float sum = -0x1.28b0960000000p-5f;
    for (unsigned j = 0; j < 31; ++j)
        if (x[j] != x[j] || x[j] > FLT_MAX || x[j] < -FLT_MAX) return -1.0f;
    for (unsigned t = 0; t < 50; ++t) {
        uint16_t i = root[t];
        while (feature[i] != 255) i = x[feature[i]] <= value[i] ? left[i] : right[i];
        sum += value[i];
    }
    return 1.0f / (1.0f + expf(-sum));
}
